type TranslationFn = (
  key: string,
  options?: Record<string, unknown>
) => unknown;

type MetricItem = {
  label: string;
  value: string;
  note?: string;
};

export type CaseStudyProofSource = {
  client: string;
  businessType: string;
  challenges: string[];
  interventions: string[];
  results: string[];
  metrics: MetricItem[];
  href: string;
};

const normalizeList = (input: unknown): string[] => {
  if (!Array.isArray(input)) return [];

  return input
    .map((item) => {
      if (typeof item === "string") return item.trim();
      if (item && typeof item === "object" && "item" in item) {
        return String((item as { item?: string }).item || "").trim();
      }
      return "";
    })
    .filter(Boolean);
};

const normalizeMetrics = (input: unknown): MetricItem[] => {
  if (!Array.isArray(input)) return [];

  return input
    .map((item) => {
      if (!item || typeof item !== "object") return null;

      const metric = item as {
        label?: string;
        value?: string;
        note?: string;
      };

      const label = String(metric.label || "").trim();
      const value = String(metric.value || "").trim();
      const note = String(metric.note || "").trim();

      if (!label || !value) return null;

      return { label, value, ...(note ? { note } : {}) };
    })
    .filter((item): item is MetricItem => Boolean(item));
};

export const getCaseStudyProofSource = (
  t: TranslationFn,
  slug: string
): CaseStudyProofSource => ({
  client: String(t(`caseStudies.items.${slug}.name`, { defaultValue: "" }) || ""),
  businessType: String(
    t(`caseStudies.items.${slug}.businessType`, {
      defaultValue: t(`caseStudies.items.${slug}.projectType`, {
        defaultValue: "",
      }),
    }) || ""
  ),
  challenges: normalizeList(
    t(`caseStudies.items.${slug}.challenge`, {
      returnObjects: true,
      defaultValue: [],
    })
  ),
  interventions: normalizeList(
    t(`caseStudies.items.${slug}.delivered`, {
      returnObjects: true,
      defaultValue: [],
    })
  ),
  results: normalizeList(
    t(`caseStudies.items.${slug}.results`, {
      returnObjects: true,
      defaultValue: [],
    })
  ),
  metrics: normalizeMetrics(
    t(`caseStudies.items.${slug}.metrics`, {
      returnObjects: true,
      defaultValue: [],
    })
  ),
  href: `/portfolio/case-studies/${slug}/`,
});
